#!/usr/bin/env python3
"""Turn 35 Wave 96: THE 84+ RULE, THE BLUE-CARD TRAP, AND A DISSENT AGAINST 4-2-3-1.

Wave 96's centrepieces:

1. THE 84+ PURCHASE RULE, from two independent voices: buy only players rated 84 and above,
   because they give the best chance of winning - and save your money until one appears. The
   corollary is the **blue-card trap**: rare cards in the market are often expensive AND below
   75 OVR, at double the cost of a 65-70 common, with attribute differences that do not show up
   in matches. **Secret player offers, by contrast, are worth taking above about 1,200 coins.**

2. THE GREY-GOALKEEPER ROUTE, which closes a gap in the corpus's coaching economy. The corpus
   says do not spend gems on goalkeeper coaches; this wave supplies the coin alternative - buy
   grey goalkeepers (the cheapest players in the game) and release them for GK coaches. Paired
   with the 1,400-coin legendary-to-rare-coach route, that is a complete coin-only coaching
   ladder.

3. A DISSENT AGAINST 4-2-3-1 - the corpus's most-recommended formation. One source says never
   use it: the striker has zero support and it is punished by long balls. That is a genuine
   disagreement with a Tier 1 player's own preferred shape, and it is recorded as a dissent
   rather than smoothed into consensus.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w96')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_tm=new_ev("r/DreamLeagueSoccer 1rcmvcn 'Tips to improve your team' (23 Feb 2026 - the 84+ purchase rule, the fan-buy caution, and the one-part-at-a-time stadium rule), r/DreamLeagueSoccer ktwxpz 'A Beginner's Guide to DLS' (9 Jan 2021 - the blue-card trap and the 1.2k secret-player threshold), r/DreamLeagueSoccer 15bpnih (28 Jul 2023 - the don't-buy-scouts rule and the grey-goalkeeper-to-GK-coach route), r/DreamLeagueSoccer zzp2l0 (31 Dec 2022 - the team-rating 80 market threshold), r/DreamLeagueSoccer 1gaazjq (23 Oct 2024 - the buy-highest-rated-to-raise-strength loop), r/DreamLeagueSoccer 166iw2k (31 Aug 2023 - the 1,400-coin legendary-to-rare-coach route and the minute-70 forfeit), r/DreamLeagueSoccer 18a2llb (3 Dec 2023 - 36 matches without the wanted player), r/DreamLeagueSoccer 176ntor (13 Oct 2023 - the formation list including the 'never use 4-2-3-1' dissent), r/DreamLeagueSoccer 1sqlpov (20 Apr 2026 - a player's four-formation rotation), r/DreamLeagueSoccer 18d0t57 (7 Dec 2023 - the 4-1-2-3 case), LevelWinner DLS2024 formations guide (15 Mar 2024 - 4-5-1 works with common players), plus a seventh contamination from EA FC trading methods and generic formation guides",
    "THE 84+ RULE, THE BLUE-CARD TRAP, THE GREY-GOALKEEPER ROUTE, AND A DISSENT AGAINST 4-2-3-1. (1) THE 84+ PURCHASE RULE, from two independent voices: '**save money and wait for those 84-86 players** unless you are big fan of someone/some team, and you do need gold for your stadium anyway for higher league' and '**I advise you to buy only 84 and above players rating as they give the best chance of winning.**' The fan-buy caution attached to it: 'Even if you are a die hard fan of messi or ronaldo id advice not to buy them now as **their performance is not good as compared to other better players** but you can buy them for the sake of keeping them.' (2) THE BLUE-CARD TRAP: '**Be careful with secret player and rare player appearances in your transfers. Often the rare players that'll appear will be expensive and <75 OVR. The blue cards may look appealing but they'll be at double the expense of 65-70 OVR common (silver) players and the attribute differences aren't that significant performance wise in matches so treat them as a trap.**' So the card colour is not a quality signal - it is a price signal, and often a bad one. (3) THE SECRET-PLAYER THRESHOLD, the exception: '**secret player offers will be of great benefit if they're >1.2k in cost**' - so a discounted secret offer above about 1,200 coins is worth taking, while an expensive blue card below 75 is not. (4) THE DON'T-BUY-SCOUTS RULE: '**Don't. buy. scouts.** I know how tempting it may seem to buy a scout for that small chance that maybe you may just get that 86 overall Kylian Mbappe with your gray team. But to be frank, you're not gonna get it... The only thing I had gotten from it was a CR7 and a Yassine Bonou. Even then, that was after spending 4,000 coins just trying to see what I get. **Do not buy common or rare coaches.**' (5) THE GREY-GOALKEEPER ROUTE, which closes a gap in the corpus's coaching economy: '**Don't use gems for goalkeeper coaches.** It comes as no surprise to anyone that goalkeepers are among the cheapest players in all of DLS. However, spending gems of goalkeeper coaches is just an overall bad idea... **You'll find that it is much cheaper to spend coins on gray goalkeepers and then immediately selling them for goalkeeper coaches.**' So the corpus's 'no gems on GK coaches' rule now has its coin alternative. (6) THE TEAM-RATING MARKET THRESHOLD: '**You can get good players after like 75 but you'll definitely get the best players once you hit 80**' and 'good players will arrive when your team rating is 80.0+' - which is the mechanism behind the corpus's market-quality-tracks-OVR finding, with a number. (7) THE BUY-HIGHEST-RATED LOOP: '**buy the highest rated players every time the market refreshes, this will increase your team strength and accordingly you'll attract more better players (rare, legendary ones)**' with the worked example 'if you buy a 74 rated player maybe after 2-3 matches you might get a 79 rated' and 'if you see 2 rare players in the market at the same time i'd suggest to buy the highest rated player.' (8) THE 1,400-COIN LEGENDARY-TO-RARE-COACH ROUTE: 'I've maxed my stadium, and I've been using coins to **buy the cheapest legendary player in the transfer market (usually around 1400) and then I immediately release them for a rare coach**' - a second rung on the coin-only coaching ladder, above the grey-goalkeeper and 80-rated-defender routes. (9) THE PATIENCE REQUIREMENT: 'It takes time, **I've played like 36 matches and still haven't gotten the player I wanted** in the transfer market. The fastest way to do it is probably just buy legendary scouts' - so the wanted-player search is a long game, and the corpus's 'wait for 84+' rule has a real cost in matches. (10) THE MINUTE-70 FORFEIT: 'If you want to face easy competition in live, **play until minute 70 that way you can forfeit**' - a way to lose on purpose while still farming the early part of a match. (11) A DISSENT AGAINST 4-2-3-1, the corpus's most-recommended formation: '**Never use 4-2-3-1, if you can. Striker has zero support all the time, and still punished by long balls.**' That is a genuine disagreement with a Tier 1 player's own preferred shape, and it is recorded as a dissent rather than smoothed into consensus. (12) THE 4-5-1 FINDING: '**It can work even if your lineup still has a lot of white/common players.** Verdict: 4-5-1 is best used as a reactionary tactic when you want to preserve the score' - so there is a shape that works with a weak squad, which matters for the F2P climb. (13) THE 4-1-2-3 CASE: 'it reinforced my defence with the addition of a DM. The 2 CMs in the front can act both as attackers and midfielders.' (14) A SEVENTH CONTAMINATION: both searches returned EA FC trading methods (sniping filters, SBC demand cycles, the 5% EA tax, FUTBIN) and generic formation guides. Seven waves, seven contaminations.",
    "THE 84+ PURCHASE RULE from two independent voices - buy only 84 and above, and save until one appears. THE BLUE-CARD TRAP: rare cards in the market are often expensive AND below 75 OVR, at double the cost of a 65-70 common, with attribute differences that do not show up in matches - so card colour is a price signal, not a quality one. THE SECRET-PLAYER THRESHOLD: offers above about 1,200 coins are worth taking. THE DON'T-BUY-SCOUTS RULE (4,000 coins spent for a CR7 and a goalkeeper). THE GREY-GOALKEEPER ROUTE - the coin alternative to the corpus's no-gems-on-GK-coaches rule. THE TEAM-RATING 80 MARKET THRESHOLD. THE BUY-HIGHEST-RATED LOOP. THE 1,400-COIN LEGENDARY-TO-RARE-COACH ROUTE. THE MINUTE-70 FORFEIT for easier competition. A DISSENT AGAINST 4-2-3-1 - the corpus's most-recommended formation - recorded as a dissent, not smoothed. AND THE 4-5-1 WORKS WITH COMMON PLAYERS.",
    "THE 84+ RULE, THE BLUE-CARD TRAP, AND A DISSENT AGAINST 4-2-3-1",
    quality="community")

add_claim("THE 84+ PURCHASE RULE, from two independent voices: '**save money and wait for those 84-86 players** unless you are big fan of someone/some team, and you do need gold for your stadium anyway for higher league' and '**I advise you to buy only 84 and above players rating as they give the best chance of winning.**' The fan-buy caution attached: 'Even if you are a die hard fan of messi or ronaldo id advice not to buy them now as **their performance is not good as compared to other better players** but you can buy them for the sake of keeping them.'", 3, "transfers/84-plus-purchase-rule", [e_tm])
add_claim("THE BLUE-CARD TRAP: '**Be careful with secret player and rare player appearances in your transfers. Often the rare players that'll appear will be expensive and <75 OVR. The blue cards may look appealing but they'll be at double the expense of 65-70 OVR common (silver) players and the attribute differences aren't that significant performance wise in matches so treat them as a trap.**' **So the card colour is not a quality signal - it is a price signal, and often a bad one.**", 3, "transfers/blue-card-trap", [e_tm], notes="A direct warning against the corpus's card-colour taxonomy being read as quality")
add_claim("THE SECRET-PLAYER THRESHOLD, the exception to the trap: '**secret player offers will be of great benefit if they're >1.2k in cost.**' So a discounted secret offer above about 1,200 coins is worth taking, while an expensive blue card below 75 OVR is not - which gives the market a simple two-line rule.", 3, "transfers/secret-player-1200-threshold", [e_tm])
add_claim("THE DON'T-BUY-SCOUTS RULE: '**Don't. buy. scouts.** I know how tempting it may seem to buy a scout for that small chance that maybe you may just get that 86 overall Kylian Mbappe with your gray team. But to be frank, you're not gonna get it... The only thing I had gotten from it was a CR7 and a Yassine Bonou. Even then, that was after spending 4,000 coins just trying to see what I get. **Do not buy common or rare coaches.**' A dissent against the corpus's scout-hiring advice, with the cost of the experiment named.", 4, "transfers/dont-buy-scouts-dissent", [e_tm], notes="A minority position against the corpus's scout guidance; the 4,000-coin anecdote is the evidence")
add_claim("THE GREY-GOALKEEPER ROUTE, which closes a gap in the corpus's coaching economy: '**Don't use gems for goalkeeper coaches.** It comes as no surprise to anyone that goalkeepers are among the cheapest players in all of DLS. However, spending gems of goalkeeper coaches is just an overall bad idea... **You'll find that it is much cheaper to spend coins on gray goalkeepers and then immediately selling them for goalkeeper coaches.**' So the corpus's no-gems-on-GK-coaches rule now has its coin alternative.", 3, "coaching/grey-goalkeeper-to-gk-coach", [e_tm])
add_claim("THE TEAM-RATING MARKET THRESHOLD: '**You can get good players after like 75 but you'll definitely get the best players once you hit 80**' and 'good players will arrive when your team rating is 80.0+' - the mechanism behind the corpus's market-quality-tracks-OVR finding, with a number attached.", 3, "transfers/team-rating-80-market-threshold", [e_tm])
add_claim("THE BUY-HIGHEST-RATED LOOP: '**buy the highest rated players every time the market refreshes, this will increase your team strength and accordingly you'll attract more better players (rare, legendary ones)**' - with the worked example 'if you buy a 74 rated player maybe after 2-3 matches you might get a 79 rated' and 'if you see 2 rare players in the market at the same time i'd suggest to buy the highest rated player.' So each purchase is a bid for a better market, not just a better player.", 3, "transfers/buy-highest-rated-loop", [e_tm])
add_claim("THE 1,400-COIN LEGENDARY-TO-RARE-COACH ROUTE, a second rung on the coin-only coaching ladder: 'I've maxed my stadium, and I've been using coins to **buy the cheapest legendary player in the transfer market (usually around 1400) and then I immediately release them for a rare coach.**' Above the grey-goalkeeper and 80-rated-defender routes, and it uses the cheapest legendary rather than the cheapest defender.", 3, "coaching/1400-coin-legendary-to-rare-coach", [e_tm])
add_claim("THE PATIENCE REQUIREMENT for the wanted-player search: 'It takes time, **I've played like 36 matches and still haven't gotten the player I wanted** in the transfer market. The fastest way to do it is probably just buy legendary scouts.' So the corpus's 'wait for 84+' rule has a real cost in matches, and the manager-name and club-name levers exist precisely to shorten it.", 3, "transfers/patience-36-matches", [e_tm])
add_claim("THE MINUTE-70 FORFEIT: 'If you want to face easy competition in live, **play until minute 70 that way you can forfeit.**' A way to lose on purpose while still farming the early part of a match - and it pairs with the corpus's concede-without-playing Career tactic as the two time-saving exits.", 3, "dll/minute-70-forfeit", [e_tm])
add_claim("A DISSENT AGAINST 4-2-3-1, the corpus's most-recommended formation: '**Never use 4-2-3-1, if you can. Striker has zero support all the time, and still punished by long balls.**' That is a genuine disagreement with a Tier 1 player's own preferred shape, and it is recorded as a dissent rather than smoothed into consensus - the corpus's own C-014 explains why: shapes differ by failure mode, and 4-2-3-1's failure mode is an isolated striker.", 3, "tactics/never-use-4-2-3-1-dissent", [e_tm], notes="A real dissent against a corpus recommendation, preserved rather than averaged away")
add_claim("THE 4-5-1 FINDING: '**It can work even if your lineup still has a lot of white/common players.** Verdict: 4-5-1 is best used as a reactionary tactic when you want to preserve the score' - so there is a shape that works with a weak squad, which matters directly for the F2P climb and for defending a lead.", 3, "tactics/4-5-1-works-with-commons", [e_tm])
add_claim("THE 4-1-2-3 CASE, from a player who tried most formations: 'it reinforced my defence with the addition of a DM. The 2 CMs in the front can act both as attackers and midfielders.' So the shape's value is that its front two are dual-role, which is the same property the corpus records for 4-4-2's wide midfielders.", 3, "tactics/4-1-2-3-case", [e_tm])
add_claim("A SEVENTH CONTAMINATION: both searches returned EA FC trading methods (sniping filters, SBC demand cycles, the 5% EA tax, FUTBIN, FUT Chief) and generic formation guides. Seven waves, seven contaminations - the general rule from wave 88 now has seven instances behind it.", 3, "errata/seventh-contamination", [e_tm])

for p in ['EV-509_transfer_market_practice.html','EV-509b_formation_dissent.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
